    add('steelSatin', F.boxAt(0.3, 0.32, 0.3, X - 0.5, 1.2, 0)); add('steelSatin', F.cylAB([X - 0.66, 1.2, 0], [X - 0.72, 1.2, 0], 0.24, 20));
    add('steelSatin', F.boxAt(0.3, 0.42, 0.3, X, 1.62, 0)); add('accent', wheel(0.14, 0.015, X, 1.62, 0.2, 0, 0));   // swab
