// ═══════════════════════════════════════════════════════════════════
// §D SESSION STATE (survives navigation within the page session, D10)
// ═══════════════════════════════════════════════════════════════════
var _sim = null;            // the live sim instance
var _lastFlowObj = null;    // identity of the last flow handed to the sim (K57: never compare seq/ts)
var _resetPending = false;  // project Open/New → reset on the next applied flow
var _alarmMap = {};         // operator lifecycle map (UNACK/ACK/RTN)
var _ctl = null;            // current controller
var _sessionHooked = false;
var _rigPending = false;     // project Open/New → re-apply the saved rig-up on the next applied flow

function hookSession() {
    if (_sessionHooked || typeof document === 'undefined' || !document.addEventListener) return;
    _sessionHooked = true;
    var onProj = function () { _resetPending = true; _alarmMap = {}; _rigPending = true; };
    document.addEventListener('wts:project-loaded', onProj);
    document.addEventListener('wts:project-new', onProj);
}

function readPrefs() {
    var p = {}, k;
    for (k in PREF_DEFAULTS) p[k] = PREF_DEFAULTS[k];
    try {
        var raw = G.localStorage && G.localStorage.getItem(PREFS_KEY);
        var o = raw ? JSON.parse(raw) : null;
        if (o && typeof o === 'object') {
            if (o.mode === '3d' || o.mode === '2d') p.mode = o.mode;
            if (/^(all|equip|off)$/.test(o.labels)) p.labels = o.labels;
            if (/^(phase|pressure|temperature|erosion)$/.test(o.overlay)) p.overlay = o.overlay;
            if (/^(auto|high|medium|low)$/.test(o.quality)) p.quality = o.quality;
            if (SPEEDS.indexOf(+o.speed) >= 0) p.speed = +o.speed;
            ['legend', 'trends', 'orbit'].forEach(function (b) { if (typeof o[b] === 'boolean') p[b] = o[b]; });
            // operator lineup (divert valves, pump suction, auto-divert): shape-checked here, value-checked by WTS_sim.setControls
            if (o.ctl && typeof o.ctl === 'object' && o.ctl.surge && typeof o.ctl.surge === 'object' && o.ctl.gauge && typeof o.ctl.gauge === 'object') p.ctl = deepClone(o.ctl);
            if (o.cushion !== undefined) p.cushion = cushionPrefs(o.cushion);
        }
    } catch (e) {}
    if (!p.cushion) p.cushion = cushionPrefs(null);
    return p;
}
function writePrefs(p) {
    try {
        if (!G.localStorage) return;
        var o = p;
        if (p && typeof p === 'object' && Object.prototype.hasOwnProperty.call(p, 'cushion')) {   // the cushion form block is validated on the way out too
            o = {}; for (var k in p) if (Object.prototype.hasOwnProperty.call(p, k)) o[k] = p[k];
            o.cushion = cushionPrefs(p.cushion);
        }
        G.localStorage.setItem(PREFS_KEY, JSON.stringify(o));
    } catch (e) {}
}
// v1.5.0 cushion-unload form values (Scenarios → Cushion unload; device prefs, not host inputs — docs/SIM-FOLLOWUP-PLAN.md D5,
// §3.4): {V bbl, SG, q bbl/d, tbg (tubing size id → capacity), depth ft}, each clamped by WTS_sim.DEFAULTS.cushion.lim; a missing
// or invalid field takes the default (D7)
var CUSH_TBG = [['2-3/8', 0.00387, '2-3/8″ 4.7 lb/ft (1.995″ ID)'], ['2-7/8', 0.00579, '2-7/8″ 6.5 lb/ft (2.441″ ID)'],
    ['3-1/2', 0.00870, '3-1/2″ 9.2 lb/ft (2.992″ ID)'], ['4-1/2', 0.01522, '4-1/2″ 12.75 lb/ft (3.958″ ID)']];
var CUSH_LIM = { V: [1, 500], SG: [0.80, 1.50], q: [100, 6000], depth: [500, 25000] };
function cushionDefs() {
    var S = G.WTS_sim, C = S && S.DEFAULTS && S.DEFAULTS.cushion ? S.DEFAULTS.cushion : null, L = C && C.lim ? C.lim : CUSH_LIM;
    return { d: { V: num(C && C.V_bbl, 50), SG: num(C && C.SG, 1.03), q: num(C && C.q_bpd, 1500), tbg: '3-1/2', depth: num(C && C.depth_ft, 10000) },
        lim: { V: L.V || CUSH_LIM.V, SG: L.SG || CUSH_LIM.SG, q: L.q || CUSH_LIM.q, depth: L.depth || CUSH_LIM.depth } };
}
function cushionPrefs(o) {
    var D = cushionDefs(), out = { V: D.d.V, SG: D.d.SG, q: D.d.q, tbg: D.d.tbg, depth: D.d.depth };
    if (!o || typeof o !== 'object' || Array.isArray(o)) return out;
    ['V', 'SG', 'q', 'depth'].forEach(function (k) { var v = o[k]; if (isNum(v)) out[k] = clamp(v, D.lim[k][0], D.lim[k][1]); });
    for (var i = 0; i < CUSH_TBG.length; i++) if (o.tbg === CUSH_TBG[i][0]) out.tbg = o.tbg;
    return out;
}
function cushionCap(tbg) { for (var i = 0; i < CUSH_TBG.length; i++) if (CUSH_TBG[i][0] === tbg) return CUSH_TBG[i][1]; return 0.00870; }
// ── v1.5.0 HMI (WP-L, docs/SIM-FOLLOWUP-PLAN.md §8.3): CK-102 card, bypass destination, cushion unload ──
var CUSH_SCEN = 'Cushion unload (clean-up)';                       // Scenarios menu entry (_wts-fu-shapes LABELS.scenario)
var CK2_BYP = 'Bypassed with H-101';                                // CK-102 in the rig-up, heater bypassed or H-101 out
var CUSH_PHASE_TXT = { off: 'off', unloading: 'unloading', stalled: 'STALLED (no lift)', breakthrough: 'gas breakthrough', tail: 'tail', done: 'recovered' };
// the cushion form → startCushion options (the keys of WTS_sim.DEFAULTS.cushion.lim: V bbl, SG, q bbl/d, cap bbl/ft, depth ft)
function cushionOpts(p) { var c = cushionPrefs(p); return { V: c.V, SG: c.SG, q: c.q, cap: cushionCap(c.tbg), depth: c.depth }; }
// CK-102: in the rig-up (strictly true) but not in line — heater bypassed or H-101 out (§3.4 predicate; the node flag when present)
function ck2Bypassed(st) {
    if (!rigIn(st, 'heaterChoke')) return false;
    var n = st && st.nodes && st.nodes.heaterChoke;
    if (n && typeof n.bypassed === 'boolean' && n.inRig === true) return n.bypassed;
    var h = st && st.nodes && st.nodes.heater, I = (st && st.inputs) || {};
    return rigOut(st, 'heater') || !!(h && h.bypass != null ? h.bypass : I.bypass);
}
function ck2Active(st) { return rigIn(st, 'heaterChoke') && !ck2Bypassed(st); }
// V-101 out: destination of the whole stream (snapshot sepBy; older snapshots: the burner / flare line)
function sepByOf(st) { var b = st && st.sepBy; return b && typeof b === 'object' ? b : { dest: 'flare', P_psig: 150, P0_psig: 5, active: false, vent: false, note: '' }; }
function bypLine(st) { return rigOut(st, 'separator') && sepByOf(st).dest === 'line'; }
function ventOn(st) { return bypLine(st) && (sepByOf(st).vent === true || rigOut(st, 'flare')); }
function destTxt(st) { var b = sepByOf(st); return b.dest === 'line' ? 'production line (' + fmtU(b.P_psig, 'pressureG') + ')' : 'burner / flare line'; }
function cushOf(st) { var c = st && st.cushion; return c && typeof c === 'object' && typeof c.phase === 'string' ? c : null; }
function cushShown(st) { var c = cushOf(st); return !!(c && c.phase !== 'off'); }
// Rig-up items [{key, tag, name, locked, why}] from WTS_sim (fallback: local list)
function rigItems() {
    var S = G.WTS_sim;
    if (S && Array.isArray(S.RIGUP) && S.RIGUP.length) return S.RIGUP;
    return RIG_FALLBACK.map(function (r) {
        var it = { key: r[0], tag: r[1], name: r[2], locked: !!r[3], why: '' };
        if (r[4]) { it.optional = true; it.def = false; }
        return it;
    });
}
// default state of a rig-up item (WTS_sim.RIG_DEFAULTS; fallback: core in, optional out)
function rigDef(it) { return it.optional ? it.def === true : it.def !== false; }
// requested value of item it in request rq (D2): a missing key → the item's default; optional items are in only when
// strictly true, core items unless false
function rigReqVal(rq, it) {
    if (!rq || !Object.prototype.hasOwnProperty.call(rq, it.key) || rq[it.key] == null) return rigDef(it);
    return it.optional ? rq[it.key] === true : rq[it.key] !== false;
}
// saved rig-up request {key: bool} (only booleans for known keys; anything else → null = full rig-up)
function readRig() {
    try {
        var raw = G.localStorage && G.localStorage.getItem(RIG_KEY);
        var o = raw ? JSON.parse(raw) : null;
        if (!o || typeof o !== 'object' || Array.isArray(o)) return null;
        var out = {}, n = 0;
        rigItems().forEach(function (it) { if (typeof o[it.key] === 'boolean') { out[it.key] = o[it.key]; n++; } });
        return n ? out : null;
    } catch (e) { return null; }
}
// The default request (= RIG_DEFAULTS: every core item in, both optional items out) removes the key; any other request is
// stored with every item key (a request with only an optional item in must be kept).
function writeRig(r) {
    try {
        if (!G.localStorage) return;
        var out = {}, dflt = true;
        rigItems().forEach(function (it) { var v = rigReqVal(r, it); out[it.key] = v; if (v !== rigDef(it)) dflt = false; });
        if (dflt) G.localStorage.removeItem(RIG_KEY); else G.localStorage.setItem(RIG_KEY, JSON.stringify(out));
    } catch (e) {}
}
// v1.5.0 (docs/SIM-FOLLOWUP-PLAN.md §3.4, §4.5): hand the effective rig-up to the host's display-only renderer of the
// rig-dependent result rows (CK-102 rbox, node-table rows, warnings). It never saves, dispatches wts:calc, calls setFlow or
// reads storage; a host without it (before WP-C) is left alone.
function hostResults(rig) {
    var fn = G.wtsRenderResults, L = G.WTS_lastCalc;
    if (typeof fn !== 'function' || !L || !L.flow || !rig || typeof rig !== 'object') return false;
    try { fn(L.flow, deepClone(rig)); return true; } catch (e) { return false; }
}
// equipment out of the rig-up (snapshot st.rigup; older snapshots: everything in)
function rigOut(st, id) { var r = st && st.rigup; return !!(r && r[id] === false); }
// optional equipment in the rig-up (only a strict true counts; older snapshots: out)
function rigIn(st, id) { var r = st && st.rigup; return !!(r && r[id] === true); }
// step numbers for the effective rig-up: WTS_sim.stepFor when present, else the v3.3 STEP table
function stepFor(rig) {
    var S = G.WTS_sim;
    if (S && typeof S.stepFor === 'function') { try { var m = S.stepFor(rig || {}); if (m && typeof m === 'object') return m; } catch (e) {} }
    return STEP;
}
function stepMap(st) { return stepFor(st && st.rigup); }
// surge outlet transfer LCV-201 (no pump; snapshot surge.transfer, legacy surge.pump) — short state text
function xferOf(st) { var su = st && st.surge; return su ? (su.transfer || su.pump || null) : null; }
function xferShort(st) {
    var p = xferOf(st);
    if (!p) return '—';
    if (rigOut(st, 'surge')) return 'OUT';
    return p.failed ? 'STUCK SHUT' : p.tripped ? 'TRIP' : p.blocked ? 'BLOCKED' : p.on ? (p.lowDP ? 'OPEN · LOW ΔP' : 'OPEN') : 'SHUT';
}
// P-201 (gauge tank → export / burner) — state text
function pumpShort(st) {
    var p = st && st.gauge && st.gauge.pump;
    if (!p) return '—';
    if (p.mode === 'none') return 'OUT (no gauge tank)';
    if (p.mode === 'gravity') return 'NOT IN RIG-UP · gravity drain';
    return p.failed ? 'FAILED' : p.on ? 'RUNNING' : 'STANDBY';
}
// Scenarios list [[id, label]]: ids from WTS_sim.FAULTS when present (the local FAULTS is the fallback). Order: the v3.3 local
// order for the ids 38 knows, then the remaining engine ids in WTS_sim.FAULTS order; label: the local one when 38 has one
// (more descriptive; also used by the fault toasts), else the engine label.
function faultList() {
    var S = G.WTS_sim, E = (S && Array.isArray(S.FAULTS) && S.FAULTS.length) ? S.FAULTS : null;
    if (!E) return FAULTS.map(function (x) { return [x[0], x[1]]; });
    var ids = {}, out = [];
    E.forEach(function (f) { if (f && typeof f.id === 'string') ids[f.id] = f.label || f.id; });
    FAULTS.forEach(function (x) { if (Object.prototype.hasOwnProperty.call(ids, x[0])) { out.push([x[0], x[1]]); delete ids[x[0]]; } });
    E.forEach(function (f) { if (f && Object.prototype.hasOwnProperty.call(ids, f.id)) { out.push([f.id, String(ids[f.id])]); delete ids[f.id]; } });
    return out;
}
function faultLabel(id) {
    var L = faultList();
    for (var i = 0; i < L.length; i++) if (L[i][0] === id) return L[i][1];
    for (var j = 0; j < FAULTS.length; j++) if (FAULTS[j][0] === id) return FAULTS[j][1];
    return String(id);
}
// faults of an optional item: accepted while the item is out, they act once it is added (plan §4.7) — the menu and the toast
// say so ("armed")
var FAULT_ITEM = { desanderPlugged: 'desander', desanderWashout: 'desander', desanderDumpStuck: 'desander', desanderIsoPassing: 'desander',
    desanderBypassPassing: 'desander', xfer2StuckClosed: 'surge2', bpv2StuckClosed: 'surge2' };
var FAULT_ITEM_TAG = { desander: 'DS-101', surge2: 'T-202' };
