        hv('rG', R.gas_mmscfd, 'gasRate'); setText(E.h.rGA, trendArrow('gas', R.gas_mmscfd, 1.5 * Qg));
        var oil = num(R.oilMeter_stbd, R.oil_stbd), wat = num(R.waterMeter_bpd, R.water_bpd);
